def answer(question, order=None):
    if not isinstance(question, str) or not question.strip() or len(question) > 2000:
        raise ValueError("question_required")
    question = question.strip()
    normalized = question.lower().replace("ё", "е")
    order = order if isinstance(order, dict) else None
    handoff = bool(re.search(r"позови|человек|мастер|владел|оператор|связаться", normalized))
    hits = [] if handoff else [x for x in KNOWLEDGE if re.search(x[1], normalized)]
    if order and re.search(r"статус|когда.*готов|моя.*работ|мой.*заказ|готов.*заказ|оплат|платеж", normalized):
        amount = order.get("due_now")
        amount = amount.get("amount") if isinstance(amount, dict) else None
        price = order.get("price")
        body = "Заказ № {id}: {status}.".format(id=order["id"], status=order.get("status_label") or order.get("status") or "статус уточняется")
        if type(price) is int and price > 0:
            body += f" Стоимость по смете — {price:,} ₽.".replace(",", " ")
        if type(amount) is int and amount > 0:
            body += f" Сейчас к оплате {amount:,} ₽.".replace(",", " ")
        body += " Срок: " + str(order.get("deadline_text") or order.get("deadline_date") or "ещё уточняется") + "."
        links = [("Открыть заказ", f"/dashboard.html#order-{int(order['id'])}-money")]
        source = "order"
    elif hits:
        hit = hits[0];body,links,source=hit[2],hit[3],hit[0]
    else:
        body = "Передам вопрос мастеру вместе с контекстом. Ниже можно проверить и дополнить сообщение перед отправкой." if handoff else "В опубликованных условиях нет точного ответа на этот вопрос. Лучше уточнить у мастера — подготовлю сообщение с контекстом."
        links=[("Связаться с мастером", "/priyomnaya.html")];source="handoff";handoff=True
    handoff_text = "Вопрос к мастеру: " + question
    if order:
        handoff_text += "\nЗаказ № " + str(order["id"]) + ". " + str(order.get("work_label") or "")
        handoff_text += "\nТекущий статус: " + str(order.get("status_label") or order.get("status") or "уточняется")
    return {"ok":True,"version":VERSION,"answer":body,"source":source,
            "links":[{"label":label,"url":url} for label,url in links],
            "handoff":handoff,"handoff_text":handoff_text[:2800],
            "order_id":order["id"] if order else None}
